// Derive a guaranteed-accessible directory path from a fuzz-provided file path.
// FUZZ_PARAM_FILENAME returns a valid file path (the containing directory exists),
// so we take its parent directory to satisfy the function's directory requirement.
const char *any_file_path = FUZZ_PARAM_FILENAME();
std::string parent_dir = any_file_path;
{
    // Find the last path separator; if none, use current directory '.'
    size_t slash = parent_dir.find_last_of('/') ;
    if (slash == std::string::npos) {
        parent_dir = ".";
    } else if (slash == 0) {
        // Root directory case: '/...'; parent is '/'
        parent_dir = "/";
    } else {
        parent_dir = parent_dir.substr(0, slash);
    }
}

// Ensure file_names is a valid, modifiable vector; the runtime guarantees non-null.
// We preserve existing contents and only append per API contract.
int rc = read_files_in_dir(parent_dir.c_str(), *file_names);
// If we somehow derived an inaccessible directory (should be rare), treat as a constraint failure.
if (rc == -1) { FUZZ_BAIL(); }

// file_names is returned as an output for persistence in the object pool.

// Capture the original input; API guarantees the input reference is not modified.
const std::string original = *str;

// Invoke the target function. It returns a new string; input must remain unchanged.
std::string trimmed = trim_leading_whitespace(*str);

// Property: input string must be unchanged by the operation.
FUZZ_ASSERT(*str == original, "trim_leading_whitespace must not modify its input");

// We do not need to persist 'trimmed' as an object; it is a value. The input 'str' remains persistent.

// Generate a finite float and a non-negative precision n.
float a_value = *FUZZ_PARAM(float);
int n = (int)(*FUZZ_PARAM(unsigned int) % 10); // keep n small (0..9) to avoid excessive sizes

// Call the function under test.
std::string out = to_string_with_precision(a_value, n);

// Basic property: result should not be empty for any finite input under fixed formatting.
FUZZ_ASSERT(!out.empty(), "to_string_with_precision returned empty string");

// Provide a readable text file path; FUZZ_PARAM_FILENAME creates a valid file with random data.
const char *path = FUZZ_PARAM_FILENAME();
std::string fname(path);

// Invoke the target function. It always returns 0 per contract, regardless of I/O success.
int rc = read_labels(fname, *labels_map);
FUZZ_ASSERT(rc == 0, "read_labels must always return 0");

// labels_map remains in the pool as it is modified/extended by the call.

// Construct a std::vector<std::string> with a small, bounded number of entries.
std::vector<std::string> *file_names = new (std::nothrow) std::vector<std::string>();
if (!file_names) { FUZZ_BAIL(); }

// Generate a base string once (looping FUZZ_PARAM_STR() would repeat the same value anyway).
std::string base = FUZZ_PARAM_STR();

// Append up to 7 entries to keep allocations small.
unsigned int count = (*FUZZ_PARAM(unsigned int) % 8); // 0..7 entries
for (unsigned int i = 0; i < count; ++i) {
    // Derive distinct values without additional fuzz calls; duplicates are acceptable too.
    file_names->push_back(base + std::string("_") + std::to_string(i));
}

// Track size for potential downstream constraints.
FUZZ_SET_ATTR_INT(file_names, "size", (int)file_names->size());

// Validation: output is allocated and non-null; contents count is bounded (<=7).

