std::string seed = FUZZ_PARAM_STR();

// Optionally trim or mutate to create variability without extra fuzz calls.
size_t keep = seed.size() ? (*FUZZ_PARAM(unsigned int) % (seed.size())) : 0;
std::string derived = seed.substr(0, keep) + std::string("_") + std::to_string((unsigned long long)keep);

std::string *str = new (std::nothrow) std::string(derived);
if (!str) { FUZZ_BAIL(); }

// Track metadata for downstream checks.
FUZZ_SET_ATTR_INT(str, "length", (int)str->size());

// Validation: output is allocated and non-null; size attribute reflects the constructed string length.

// Construct a std::unordered_map<int, std::string> with sequential keys starting at 0.
std::unordered_map<int, std::string> *labels_map = new (std::nothrow) std::unordered_map<int, std::string>();
if (!labels_map) { FUZZ_BAIL(); }

