std::string base = FUZZ_PARAM_STR();

// Insert up to 7 entries; keys 0..N-1, values derived from base to ensure determinism.
unsigned int count = (*FUZZ_PARAM(unsigned int) % 8); // 0..7 entries
for (unsigned int i = 0; i < count; ++i) {
    (*labels_map)[(int)i] = base + std::string("_") + std::to_string((unsigned long long)i);
}

// Record metadata for downstream stubs (e.g., read_labels expectations about sequential keys).
