import random
from typing import List

def _rand_spaces(r: random.Random, max_count: int = 6) -> str:
    return " " * r.randint(0, max_count)

def _weighted_choice(r: random.Random, items):
    total = sum(w for _, w in items)
    pick = r.uniform(0, total)
    upto = 0.0
    for item, w in items:
        if upto + w >= pick:
            return item
        upto += w
    return items[-1][0]

def _gen_label_line(r: random.Random, index: int) -> str:
    # Create a variety of lines to exercise trim_leading_whitespace and map insertion
    # Emphasize leading/trailing spaces, empty lines, long lines, unicode-ish bytes preserved
    kinds = [
        ("plain", 3.0),
        ("leading_spaces", 3.0),
        ("trailing_spaces", 2.0),
        ("both_spaces", 2.0),
        ("empty", 1.0),
        ("only_spaces", 1.0),
        ("tabs", 1.5),
        ("numbers", 1.2),
        ("punct", 1.0),
        ("long", 0.8),
        ("utf8", 0.8),
    ]
    kind = _weighted_choice(r, kinds)

    def rand_word(n_min=3, n_max=10):
        n = r.randint(n_min, n_max)
        alphabet = "abcdefghijklmnopqrstuvwxyz"
        return ''.join(r.choice(alphabet) for _ in range(n))

    if kind == "empty":
        core = ""
    elif kind == "only_spaces":
        core = _rand_spaces(r, 12)
    elif kind == "tabs":
        # Tabs should be preserved; only spaces trimmed
        core = ("\t" * r.randint(0, 3)) + rand_word() + ("\t" * r.randint(0, 3))
    elif kind == "numbers":
        core = f"{r.randint(-10000, 10000)}_{r.random():.6f}"
    elif kind == "punct":
        punct = "-_.,:/\\|!@#$%^&*()[]{}<>?+="
        core = ''.join(r.choice(punct) for _ in range(r.randint(1, 16)))
    elif kind == "long":
        chunks = [rand_word(3, 12) for _ in range(r.randint(6, 20))]
        sep = _weighted_choice(r, [(" ", 3.0), ("\t", 1.0), ("-", 1.0), ("_", 1.0)])
        core = sep.join(chunks)
    elif kind == "utf8":
        # Include multi-byte UTF-8 sequences which should be preserved
        samples = ["α", "β", "γ", "δ", "π", "漢", "字", "🙂", "é", "ç", "ñ"]
        base = rand_word(2, 6)
        inserts = ''.join(r.choice(samples) for _ in range(r.randint(1, 6)))
        core = base + inserts + rand_word(2, 6)
    else:
        # default word-based
        words = [rand_word() for _ in range(r.randint(1, 4))]
        core = ' '.join(words)

    # Add spaces per kind to exercise trimming
    if kind == "leading_spaces":
        return _rand_spaces(r) + core
    if kind == "trailing_spaces":
        return core + _rand_spaces(r)
    if kind == "both_spaces":
        return _rand_spaces(r) + core + _rand_spaces(r)
    return core

def _gen_file(r: random.Random, target_size: int) -> bytes:
    # Mix a variety of lines, including duplicates and blanks
    num_lines = r.randint(1, 120)
    lines: List[str] = []

    # Seed with some deterministic labels to test indices and overwrites when reused
    if r.random() < 0.8:
        lines.extend([
            "cat",
            " dog",              # leading space
            "bird ",             # trailing space
            "  fish  ",          # both
            "",                   # empty
            "   ",                # only spaces
            "\tindented\tname",   # tabs preserved
            "label_0",
            "label_1",
        ])

    for i in range(num_lines):
        lines.append(_gen_label_line(r, i))

    # Randomly ensure last line ends or not with newline to test getline handling
    end_with_newline = r.random() < 0.7

    # Join lines with newlines, keeping total under 4096 bytes
    content = "\n".join(lines)
    if end_with_newline:
        content += "\n"

    data = content.encode('utf-8', errors='surrogatepass')

    if len(data) > 4096:
        data = data[:4096]
        # Avoid cutting mid-UTF-8 sequence: try to trim to last newline or valid boundary
        # Find last newline within truncated data
        nl = data.rfind(b"\n")
        if nl > 0:
            data = data[:nl+1]
        else:
            # Fallback: attempt to decode by progressively trimming
            while data:
                try:
                    data.decode('utf-8')
                    break
                except UnicodeDecodeError:
                    data = data[:-1]
    return data


def generate(seed: int) -> bytes:
    r = random.Random(seed)
    # Choose a rough target size to vary behaviors, within limit
    target_size = r.randint(64, 2048)
    return _gen_file(r, target_size)
